// Generated by scripts/build.mjs — edit src/host.js instead.
/**
 * dsh-web-sub — host half.
 *
 * Responsibilities:
 *   1. run the local OpenAI-compatible bridge that fronts the web sessions;
 *   2. register the `deepseek-web` / `gemini-web` providers in `llm-pi-ai`;
 *   3. own the credential slots those providers read;
 *   4. expose the login/status RPCs the settings panel calls.
 *
 * @module dsh-web-sub
 */
import { appendFileSync, existsSync, mkdirSync, readFileSync, statSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

import { startBridge, catalogueFor, DEFAULT_PORT } from './server.js'
import { captureFromDefaultBrowser, findChromiumBrowser, defaultBrowser } from './browser-login.js'
import { auditVideo, checkVisualQcStatus, auditKeyframeSafeAreas, verifySubtitleAudioParity } from './visual-qc.js'
import { VirtualTimeline } from './timeline-sandbox.js'
import { defaultTransactionManager } from './transactions.js'
import { getLatestFrame, setLatestFrame, buildVisualFeedbackPayload } from './visual-feedback.js'
import { DeepSeekWebClient } from './providers/deepseek.js'
import { GeminiWebClient } from './providers/gemini.js'
import {
  DATA_DIR,
  maskAccount,
  readAccounts,
  readBindFlag,
  removeAccount,
  setAccount,
  writeBindFlag,
} from './store.js'

const HERE = dirname(fileURLToPath(import.meta.url))
const WASM_PATH = process.env.DSH_WEB_SUB_WASM || join(HERE, '..', 'assets', 'sha3_wasm_bg.wasm')

const ROUTE_PREFIX = '/_dsh/dsh-web-sub'
const PROVIDER_IDS = ['deepseek-web', 'gemini-web']

/**
 * Credential slot each provider reads from.
 *
 * The slot name is only an identifier. What goes *inside* it must be
 * header-safe: DSH resolves `apiKeyEnv` and puts the value straight into an
 * `Authorization` header, so a raw Cookie header (with `;`, `=` and folded
 * newlines) makes the provider fail to load with
 * "the API key ... contains characters no HTTP header can carry".
 *
 * The real credentials never leave `accounts.json`: the bridge reads them
 * there and ignores `Authorization` entirely. The slot only needs a
 * non-empty opaque token so DSH keeps the provider visible and selectable.
 */
const API_KEY_ENV = {
  'deepseek-web': 'WEB_DEEPSEEK_TOKEN',
  'gemini-web': 'WEB_GEMINI_COOKIE',
}

/** Header-safe placeholder written into the slot while the account is bound. */
const BRIDGE_TOKEN = 'dsh-web-sub-bridge-token'
/** Header-safe placeholder written into the slot while the account is unbound. */
const UNBOUND_TOKEN = 'dsh-web-sub-unbound'

/** Display metadata per provider. */
const PROVIDER_META = {
  'deepseek-web': { displayName: 'DeepSeek Web' },
  'gemini-web': { displayName: 'Gemini Web' },
}

const LOG_FILE = join(DATA_DIR, 'plugin.log')

function log(message) {
  console.log(`[dsh-web-sub] ${message}`)
  // The desktop host has no reachable stdout, so keep our own log: it is the
  // only way to see what the plugin did during a boot that misbehaved.
  try {
    mkdirSync(DATA_DIR, { recursive: true, mode: 0o700 })
    if (existsSync(LOG_FILE) && statSync(LOG_FILE).size > 512 * 1024) writeFileSync(LOG_FILE, '')
    appendFileSync(LOG_FILE, `${new Date().toISOString()} [${process.pid}] ${message}\n`)
  } catch {
    /* logging must never take the host down */
  }
}

/**
 * Startup kill-switches used to bisect boot problems without a rebuild.
 * One token per line in `<DATA_DIR>/skip.txt`: `bridge`, `routes`, `creds`.
 */
function readSkipFlags() {
  try {
    const raw = readFileSync(join(DATA_DIR, 'skip.txt'), 'utf-8')
    return new Set(raw.split(/[\s,]+/).map((token) => token.trim()).filter(Boolean))
  } catch {
    return new Set()
  }
}

/** True when two provider routes would describe the same thing. */
function sameRoute(left, right) {
  if (left === undefined) return false
  const keys = ['displayName', 'api', 'apiKeyEnv', 'baseURL', 'transport']
  if (keys.some((key) => left?.[key] !== right?.[key])) return false
  const a = Array.isArray(left?.models) ? left.models : []
  const b = Array.isArray(right?.models) ? right.models : []
  if (a.length !== b.length) return false
  // `reasoningEfforts` is an object per model, so it compares by content: a
  // reference comparison would report a difference on every boot and rewrite
  // the settings — which emits a change event, and that can restart the host.
  const sameEfforts = (one, other) => JSON.stringify(one ?? null) === JSON.stringify(other ?? null)
  return a.every((model, index) => model?.id === b[index]?.id
    && model?.name === b[index]?.name
    && model?.contextWindow === b[index]?.contextWindow
    && model?.maxTokens === b[index]?.maxTokens
    && sameEfforts(model?.reasoningEfforts, b[index]?.reasoningEfforts))
}

/** Resolve a service through either the direct property or the DI container. */
function service(ctx, name) {
  try {
    if (ctx[name] !== undefined) return ctx[name]
    if (typeof ctx.get === 'function') return ctx.get(name)
  } catch {
    /* inactive context, or the service is not registered */
  }
  return undefined
}

/** Read the current `llm-pi-ai` section. */
function readPiAi(settings) {
  try {
    const described = typeof settings.describe === 'function' ? settings.describe() : undefined
    const entry = Array.isArray(described) ? described.find((item) => item?.ns === 'llm-pi-ai') : undefined
    if (entry?.value !== undefined) return entry.value
  } catch {
    /* fall through to the sync getter */
  }
  try {
    return settings.get('llm-pi-ai')
  } catch {
    return undefined
  }
}

export default {
  inject: ['credentials', 'settings'],

  async apply(ctx) {
    log('apply() start')
    mkdirSync(DATA_DIR, { recursive: true, mode: 0o700 })

    // Cordis marks this context inactive the moment apply() returns, so every
    // service has to be captured now — timers and RPC handlers run afterwards.
    const credentialsService = service(ctx, 'credentials')
    const settingsService = service(ctx, 'settings')
    const timerService = service(ctx, 'timer')
    log(`services: credentials=${credentialsService !== undefined} settings=${settingsService !== undefined} timer=${timerService !== undefined}`)

    /** @type {{server: import('node:http').Server, port: number, close: Function} | null} */
    let bridge = null
    let bridgeError = null
    let lastAccountSignature = ''

    const getAccount = (provider) => {
      const accounts = readAccounts()
      return accounts[provider] ?? null
    }

    // ---------- credentials ----------
    async function syncCredential(provider) {
      const credentials = credentialsService
      if (credentials === undefined || typeof credentials.set !== 'function') return
      const account = getAccount(provider)
      const slot = API_KEY_ENV[provider]
      const bound = provider === 'deepseek-web'
        ? typeof account?.token === 'string' && account.token.trim() !== ''
        : typeof account?.cookie === 'string' && account.cookie.trim() !== ''
      // Keep the slot populated even when unbound: DSH hides providers whose
      // credential resolves to nothing, and a hidden provider cannot be picked.
      // Never write the secret itself — see API_KEY_ENV above.
      try {
        await credentials.set(slot, bound ? BRIDGE_TOKEN : UNBOUND_TOKEN)
      } catch (error) {
        log(`could not write credential ${slot}: ${error.message}`)
      }
    }

    // ---------- provider registration ----------
    async function ensureProviders() {
      const settings = settingsService
      if (settings === undefined || typeof settings.mutate !== 'function') {
        return { ok: false, code: 'settings.not-ready' }
      }
      if (bridge === null) {
        return { ok: false, code: 'bridge.down', message: bridgeError ?? 'local bridge is not listening' }
      }
      const baseURL = `http://127.0.0.1:${bridge.port}/v1`
      const current = readPiAi(settings) ?? {}
      const providers = current && typeof current === 'object' && current.providers && typeof current.providers === 'object'
        ? current.providers
        : {}

      const results = []
      for (const provider of PROVIDER_IDS) {
        const existing = providers[provider]
        // Never clobber a route the user configured by hand.
        if (existing !== undefined && existing.apiKeyEnv !== API_KEY_ENV[provider]) {
          results.push({ provider, ok: false, code: 'route.occupied' })
          continue
        }
        const models = catalogueFor(getAccount('gemini-web'))
          .filter((model) => model.provider === provider)
          .map((model) => {
            const entry = {
              id: model.id,
              name: model.name,
              contextWindow: model.contextWindow,
              maxTokens: model.maxTokens,
            }
            // Published so DSH's composer shows a thinking-level selector.
            // The field is omitted when absent: an empty object is refused by
            // the `llm-pi-ai` schema.
            if (model.reasoningEfforts !== undefined && model.reasoningEfforts !== null) {
              entry.reasoningEfforts = model.reasoningEfforts
            }
            return entry
          })
        const target = {
          displayName: PROVIDER_META[provider].displayName,
          api: 'openai-completions',
          apiKeyEnv: API_KEY_ENV[provider],
          baseURL,
          models,
          transport: 'sse',
        }
        try {
          // Writing identical settings still emits a change event, and a change
          // event during boot can restart the host — only write real deltas.
          if (sameRoute(existing, target)) {
            results.push({ provider, ok: true, unchanged: true, baseURL })
            continue
          }
          await settings.mutate('llm-pi-ai', [{ op: 'set', path: ['providers', provider], value: target }])
          results.push({ provider, ok: true, baseURL })
        } catch (error) {
          results.push({ provider, ok: false, code: 'route.write-failed', message: String(error) })
        }
      }
      log(`routes: ${JSON.stringify(results)}`)
      return { ok: results.some((entry) => entry.ok), results }
    }

    // ---------- bridge lifecycle ----------
    async function startBridgeOnce() {
      if (bridge !== null) return bridge
      const preferredPort = Number(process.env.DSH_WEB_SUB_PORT) || DEFAULT_PORT
      try {
        bridge = await startBridge({
          preferredPort,
          getAccount,
          wasmPath: WASM_PATH,
          log,
        })
        bridgeError = null
        log(`bridge listening on http://127.0.0.1:${bridge.port}/v1`)
        return bridge
      } catch (error) {
        bridgeError = error.message
        log(`bridge failed to start: ${error.message}`)
        throw error
      }
    }

    // ---------- validation ----------
    async function validate(provider, credential) {
      try {
        if (provider === 'deepseek-web') {
          const client = new DeepSeekWebClient({
            token: credential.token,
            cookie: credential.cookie ?? '',
            wasmPath: WASM_PATH,
          })
          return await client.checkLogin()
        }
        if (provider === 'gemini-web') {
          const client = new GeminiWebClient({ cookie: credential.cookie })
          const check = await client.checkLogin()
          const models = Array.isArray(check.detail?.models) ? check.detail.models : undefined
          return models === undefined ? check : { ...check, models }
        }
        return { ok: false, message: `unknown provider ${provider}` }
      } catch (error) {
        return { ok: false, message: error.message }
      }
    }

    // ---------- RPC handlers ----------
    async function statusPayload() {
      const accounts = readAccounts()
      const preferred = defaultBrowser()
      const chromium = findChromiumBrowser()
      const catalogue = catalogueFor(accounts['gemini-web'] ?? null)
      const visualQc = await checkVisualQcStatus()
      const browserInfo = {
        kind: 'browser',
        displayName: 'Navegador do sistema',
        ready: preferred !== null || chromium !== null,
        isDefault: true,
      }
      const coPilot = {
        electronicEye: { ready: true, hasFrame: Boolean(getLatestFrame().base64Data) },
        activeAudit: { ready: visualQc.ready, engine: visualQc.engine },
        sandboxDom: { ready: true, engine: 'VirtualTimeline' },
        atomicTransactions: { ready: true, engine: 'ACID Rollback' },
      }
      return {
        ok: true,
        bound: Object.keys(accounts).length > 0,
        port: bridge?.port ?? null,
        baseURL: bridge === null ? null : `http://127.0.0.1:${bridge.port}/v1`,
        bridgeError,
        browser: browserInfo,
        visualQc,
        coPilot,
        flag: readBindFlag(),
        providers: Object.fromEntries(PROVIDER_IDS.map((provider) => [
          provider,
          {
            id: provider,
            displayName: PROVIDER_META[provider].displayName,
            bound: accounts[provider] !== undefined,
            account: maskAccount(accounts[provider]),
            models: catalogue.filter((model) => model.provider === provider).map((model) => model.id),
          },
        ])),
      }
    }

    async function afterBind(provider, credential, check) {
      const models = Array.isArray(check?.models) ? check.models : undefined
      setAccount(provider, {
        provider,
        ...credential,
        ...(models === undefined ? {} : { models }),
      })
      writeBindFlag({ provider })
      await syncCredential(provider)
      const route = await ensureProviders()
      lastAccountSignature = JSON.stringify(Object.keys(readAccounts()).sort())
      return route
    }

    const ROUTES = {
      async getStatus() {
        return statusPayload()
      },

      async bindManual(args) {
        const provider = String(args?.provider ?? '')
        if (!PROVIDER_IDS.includes(provider)) return { ok: false, error: `unknown provider ${provider}` }
        const token = typeof args?.token === 'string' ? args.token.trim() : ''
        const cookie = typeof args?.cookie === 'string' ? args.cookie.trim() : ''
        if (provider === 'deepseek-web' && token === '') return { ok: false, error: 'a DeepSeek token is required' }
        if (provider === 'gemini-web' && cookie === '') return { ok: false, error: 'a Gemini cookie header is required' }

        const credential = { token, cookie, source: 'manual', label: 'pasted' }
        const check = await validate(provider, credential)
        if (!check.ok) return { ok: false, error: check.message, validation: check }
        const route = await afterBind(provider, credential, check)
        return { ok: true, validation: check, route, status: await statusPayload() }
      },

      async autoLogin(args) {
        const provider = String(args?.provider ?? '')
        if (!PROVIDER_IDS.includes(provider)) return { ok: false, error: `unknown provider ${provider}` }
        let captured
        try {
          captured = await captureFromDefaultBrowser({ provider, dataDir: DATA_DIR, log })
        } catch (error) {
          return { ok: false, error: error.message }
        }
        const check = await validate(provider, captured)
        if (!check.ok) return { ok: false, error: check.message, validation: check, captured: { source: captured.source } }
        const route = await afterBind(provider, captured, check)
        return { ok: true, validation: check, route, status: await statusPayload() }
      },

      async test(args) {
        const provider = String(args?.provider ?? '')
        if (!PROVIDER_IDS.includes(provider)) return { ok: false, error: `unknown provider ${provider}` }
        const account = getAccount(provider)
        if (account === null) return { ok: false, error: 'not connected' }
        return await validate(provider, account)
      },

      /**
       * Re-read the account's model list and re-register the route.
       *
       * Google renames and re-tiers models regularly, so this is the repair
       * path when a model disappears from the picker.
       */
      async refreshModels(args) {
        const provider = String(args?.provider ?? 'gemini-web')
        if (!PROVIDER_IDS.includes(provider)) return { ok: false, error: `unknown provider ${provider}` }
        const account = getAccount(provider)
        if (account === null) return { ok: false, error: `${provider} is not connected` }
        const check = await validate(provider, account)
        if (!check.ok) return { ok: false, error: check.message }
        const models = Array.isArray(check.models) ? check.models : account.models
        if (Array.isArray(models)) setAccount(provider, { ...account, provider, models })
        const route = await ensureProviders()
        return { ok: true, models: models ?? [], route, status: await statusPayload() }
      },

      async unbind(args) {
        const provider = String(args?.provider ?? '')
        if (!PROVIDER_IDS.includes(provider)) return { ok: false, error: `unknown provider ${provider}` }
        removeAccount(provider)
        await syncCredential(provider)
        const route = await ensureProviders()
        return { ok: true, route, status: await statusPayload() }
      },

      async auditVideo(args) {
        const videoPath = args?.videoPath || args?.caminho_video || ''
        const aspectRatio = args?.aspectRatio || args?.formato || '9:16'
        const safeAreaColumnPx = Number(args?.safeAreaColumnPx || args?.coluna || 880)
        const criteria = args?.criteria || args?.criterios
        return await auditVideo({ videoPath, aspectRatio, safeAreaColumnPx, criteria, log })
      },

      async checkVisualQc() {
        return await checkVisualQcStatus()
      },

      /**
       * Pillar 3: Sandbox DOM simulation for batch operations before committing.
       */
      async simulateTimeline(args) {
        const operations = args?.operations || args?.operacoes || []
        const initialState = args?.initialState || args?.projeto || {}
        const sandbox = new VirtualTimeline(initialState)
        return sandbox.simulate(operations)
      },

      /**
       * Pillar 4: Atomic Transactions.
       */
      async beginTransaction(args) {
        const label = String(args?.label || 'batch_operation')
        const state = args?.currentState || {}
        const tx = defaultTransactionManager.begin(label, state)
        return { ok: true, txId: tx.id, label: tx.label, createdAt: tx.createdAt }
      },

      async commitTransaction(args) {
        const txId = String(args?.txId || '')
        return defaultTransactionManager.commit(txId)
      },

      async rollbackTransaction(args) {
        const txId = String(args?.txId || '')
        const reason = args?.reason || 'Manual or automated rollback requested'
        return defaultTransactionManager.rollback(txId, reason)
      },

      /**
       * Pillar 1: Electronic Eye / Real-Time Visual Feedback Loop.
       */
      async captureViewportFrame(args) {
        if (args?.base64Data) {
          setLatestFrame({
            base64Data: args.base64Data,
            format: args.format || 'image/jpeg',
            width: args.width || 1080,
            height: args.height || 1920,
            source: args.source || 'viewport',
          })
        }
        return { ok: true, frame: getLatestFrame(), payload: buildVisualFeedbackPayload(args) }
      },

      async getLatestFrame() {
        return { ok: true, frame: getLatestFrame(), payload: buildVisualFeedbackPayload() }
      },

      /**
       * Comprehensive Co-Pilot status across all 4 pillars.
       */
      async getCoPilotStatus() {
        const visualQc = await checkVisualQcStatus()
        const txStatus = defaultTransactionManager.getStatus()
        const frame = getLatestFrame()

        return {
          ok: true,
          version: '0.7.0',
          pillars: {
            electronicEye: {
              name: 'Pilar 1: Olho Eletrônico em Tempo Real',
              status: frame.base64Data ? 'ACTIVE' : 'READY_STANDBY',
              hasFrame: Boolean(frame.base64Data),
              lastCapture: frame.timestamp,
              dimensions: frame.base64Data ? `${frame.width}x${frame.height}` : '1080x1920',
            },
            activeAudit: {
              name: 'Pilar 2: Auditoria Ativa com watch-skill',
              status: visualQc.ready ? 'ACTIVE_READY' : 'STANDBY',
              engine: visualQc.engine,
              path: visualQc.path,
            },
            sandboxDom: {
              name: 'Pilar 3: Sandbox DOM em Memória',
              status: 'ACTIVE',
              engine: 'VirtualTimeline deterministic simulator',
              maxTracks: 16,
              safeAreaColumnPx: 880,
            },
            atomicTransactions: {
              name: 'Pilar 4: Transações Atômicas com Rollback',
              status: 'ACTIVE',
              activeTransactions: txStatus.activeCount,
              historyCount: txStatus.historyCount,
              latestRollbacks: txStatus.latest.filter((t) => t.status === 'ROLLED_BACK').length,
            },
          },
        }
      },
    }

    const SKIP = readSkipFlags()
    if (SKIP.size > 0) log(`startup flags: ${[...SKIP].join(', ')}`)

    // Boot the bridge first: provider routes need its real port.
    if (!SKIP.has('bridge')) {
      try {
        await startBridgeOnce()
      } catch {
        /* retried below */
      }
    }

    // Registration is deferred on purpose. `settings.mutate` while the host is
    // still finishing its boot handshake can stall or restart it, which leaves
    // the desktop window stuck invisible; let the window come up first.
    let registrationScheduled = false
    function scheduleRegistration(delayMs = 4000) {
      if (SKIP.has('routes') || registrationScheduled) return
      registrationScheduled = true
      log(`registration scheduled in ${delayMs}ms`)
      const run = () => {
        registrationScheduled = false
        ensureProviders().catch((error) => log(`deferred registration failed: ${error.message}`))
      }
      try {
        const timer = timerService
        if (timer !== undefined && typeof timer.setTimeout === 'function') {
          timer.setTimeout(run, delayMs)
          return
        }
      } catch {
        /* fall back to the global timer */
      }
      const handle = setTimeout(run, delayMs)
      if (typeof handle?.unref === 'function') handle.unref()
    }
    scheduleRegistration()

    if (!SKIP.has('creds')) {
      for (const provider of PROVIDER_IDS) await syncCredential(provider)
    }
    if (existsSync(WASM_PATH)) {
      log(`PoW wasm ready at ${WASM_PATH}`)
    } else {
      log(`WARNING: PoW wasm missing at ${WASM_PATH} — DeepSeek will fail until it is restored`)
    }

    // ---------- retry loop: bridge or settings may come up later ----------
    const timer = timerService
    if (timer !== undefined && typeof timer.setInterval === 'function') {
      try {
        timer.setInterval(async () => {
          try {
            if (bridge === null) {
              await startBridgeOnce()
              await ensureProviders()
            }
            // Re-register if the routes vanished (settings reload, profile edit).
            const settings = settingsService
            if (settings !== undefined) {
              const current = readPiAi(settings) ?? {}
              const providers = current?.providers ?? {}
              const missing = PROVIDER_IDS.some((provider) => providers[provider] === undefined)
              if (missing) await ensureProviders()
            }
            const signature = JSON.stringify(Object.keys(readAccounts()).sort())
            if (signature !== lastAccountSignature) {
              lastAccountSignature = signature
              for (const provider of PROVIDER_IDS) await syncCredential(provider)
            }
          } catch (error) {
            log(`maintenance tick failed: ${error.message}`)
          }
        }, 15000)
      } catch (error) {
        log(`could not arm maintenance timer: ${error.message}`)
      }
    }

    // ---------- web routes for the settings panel ----------
    if (typeof ctx.inject === 'function') {
      ctx.inject(['connection', 'webServer'], (webCtx) => {
        webCtx.effect(() => {
          const dispose = webCtx.webServer.register({
            kind: 'prefix',
            path: ROUTE_PREFIX,
            handler: async (req, res) => {
              const cors = {
                'access-control-allow-origin': '*',
                'access-control-allow-headers': 'content-type',
                'access-control-allow-methods': 'GET, POST, OPTIONS',
              }
              if (req.method === 'OPTIONS') {
                res.writeHead(204, cors)
                res.end()
                return
              }
              try {
                const rejection = typeof webCtx.connection?.requestRejection === 'function'
                  ? webCtx.connection.requestRejection(req)
                  : undefined
                if (rejection !== undefined) {
                  res.writeHead(rejection, { 'content-type': 'application/json', ...cors })
                  res.end(JSON.stringify({ ok: false, error: rejection === 401 ? 'authentication required' : 'request rejected' }))
                  return
                }

                const url = new URL(req.url || '/', 'http://localhost')
                if (!url.pathname.startsWith(ROUTE_PREFIX + '/')) {
                  res.writeHead(404, { 'content-type': 'application/json', ...cors })
                  res.end(JSON.stringify({ ok: false, error: 'not found' }))
                  return
                }
                const method = decodeURIComponent(url.pathname.slice(ROUTE_PREFIX.length + 1))
                if (!Object.hasOwn(ROUTES, method)) {
                  res.writeHead(404, { 'content-type': 'application/json', ...cors })
                  res.end(JSON.stringify({ ok: false, error: `unknown method ${method}` }))
                  return
                }

                let args = null
                if (req.method === 'POST') {
                  const chunks = []
                  for await (const chunk of req) chunks.push(chunk)
                  const raw = Buffer.concat(chunks).toString('utf-8')
                  if (raw.trim() !== '') {
                    try {
                      args = JSON.parse(raw)
                    } catch {
                      res.writeHead(400, { 'content-type': 'application/json', ...cors })
                      res.end(JSON.stringify({ ok: false, error: 'invalid JSON body' }))
                      return
                    }
                  }
                }

                const result = await ROUTES[method](args)
                res.writeHead(200, { 'content-type': 'application/json; charset=utf-8', ...cors })
                res.end(JSON.stringify(result))
              } catch (error) {
                log(`route ${req.url} failed: ${error.stack ?? error.message}`)
                res.writeHead(500, { 'content-type': 'application/json', ...cors })
                res.end(JSON.stringify({ ok: false, error: error.message }))
              }
            },
          })
          return () => {
            try {
              dispose()
            } catch {
              /* already disposed */
            }
          }
        }, 'dsh-web-sub: web routes')
      }, 'dsh-web-sub: web routes')
    }

    // ---------- teardown ----------
    if (typeof ctx.effect === 'function') {
      ctx.effect(() => () => {
        log('teardown: plugin unloading')
        if (bridge !== null) {
          bridge.close().catch(() => {})
          bridge = null
        }
      }, 'dsh-web-sub: bridge')
    }
  },
}
